INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(10555, 'itIT', 'Scorrendo le pagine degli appunti scribacchiati nella grafia allungata degli Arakkoa Lashh''an, ne trovi una con il simbolo dei Cerchi del Potere che hai visto a Vol Lashh.', 1),
(10556, 'itIT', 'Non so cosa dire. Quest''incantesimo è molto strano. Non è una semplice evocazione o un incantamento, ma una specie di incantesimo di comunione o comunicazione.$B$BNon saprei che dire, $N. Dovrò rifletterci ancora un po'' su.$B$BA ogni modo, grazie per il tuo aiuto! Sono certa che prima o poi lo scoprirò.', 1),
(10569, 'itIT', '<Kieran sfoglia il diario.>$B$BGran parte del diario è incomprensibile, ma riesco a leggere alcune parti e parlano tutte dei preparativi per un incantesimo sfuggito al controllo, delle vittime e della situazione che peggiora. Qui c''è una strana annotazione su un "disertore".', 1),
(10624, 'itIT', 'Il tuo mondo sta per cambiare, $N.$B$B<Hildagard comincia a creare qualcosa dalla cenere.>', 0),
(10770, 'itIT', 'Sono così tanti che non potremo mai ucciderli tutti, ma mi hai ridato speranza. Forse nei prossimi secoli mi sforzerò di più di far rivivere il mio amato bosco.', 1),
(10771, 'itIT', 'Hai distrutto molte di quelle piccole, malvagie creature. Posso riposare più serenamente sapendo che ne sono stati distrutti così tanti.', 0),
(10821, 'itIT', 'Ottima notizia, davvero ottima, $N. Non avrei potuto chiedere di meglio. I tuoi servigi al nostro popolo sono molto apprezzati. Come ricompensa, puoi scegliere uno tra questi oggetti eroici.$B$BIl tuo nome resterà inciso per sempre nei cuori della nostra gente.', 1),
(10894, 'itIT', 'È come pensavo, e questo non è un bene!$B$BHo un''idea su come aiutarti, ma prima potresti darci una mano tu?$B$BTu fai un favore a me e io ne faccio uno a te.', 1),
(10912, 'itIT', 'Sei davvero eccezionale, $R! Se già prima pensavo che fossimo in debito con te, adesso semplicemente non abbiamo modo di ripagarti.$B$BMa ci proveremo. Grazie, $geroe:eroina; di Boscovivo!', 0),
(11009, 'itIT', 'Mog''dorg mi aveva avvisato del tuo arrivo e io sono lieto che tu sia qui.$B$BEliminati i Figli di Gruul, ormai è davvero solo questione di tempo prima che i vari abitanti di questa piana montuosa e di quella più a nord si accorgano di poter predare con facilità i nostri cugini Ogre giù in basso.$B$B$N, spero proprio che tu ci voglia aiutare a impedirlo.', 1),
(11080, 'itIT', 'L''acume che dimostri nella comprensione delle reliquie ci sorprende. Il nostro suggerimento è di far pratica con le reliquie almeno una volta al giorno per mantenere allenata la tua mente.', 1),
(11122, 'itIT', 'Grazie mille! Con la Festa della Birra in corso e gli attacchi dei Nani Ferroscuro, ho bisogno d''aiuto per la consegna dei barili. Quindi, se vuoi ricevere altri biglietti, torna a parlarmi ogni giorno.$B$BMa ora basta: devo pagarti per il lavoro che hai appena svolto. Ecco i tuoi biglietti: divertiti alla Festa della Birra!', 0),
(11154, 'itIT', 'Argh... cos''è quest''odore? Ma sei tu! Be'', in effetti non ti ho certo chiesto di intraprendere una missione "profumata"!$B$BGrazie, $c. Non temere: appena ce ne andremo di qui, consegnerò questa roba a Petrov.$B$B<Feknut grida a gran voce agli esploratori.>$B$BAvete sentito? Andiamocene da questo inferno!!!', 0),
(11155, 'itIT', 'Sarà un ottimo pasto per gli uomini.$B$B<La Chef si sporge per sussurrarti in un orecchio.>$B$BTieni, $gcaro:cara;: prendine un po''. A vederti, si direbbe che tu abbia bisogno di un po'' di carne su quelle ossa!', 0),
(11227, 'itIT', 'Hai dato la caccia ai corvi cattivi, $gbello:bella;? $gBravo:Brava;! $gBravissimo:Bravissima;!$B$BAh, questi Segugi mi ricordano il periodo passato ad allevare Purosangue a Tirisfal... Quelli sì che erano bei tempi!', 0),
(11238, 'itIT', 'Accidenti se è freddo, questo corno!$B$BHai salvato il Forte di Guardia dell''Ovest ancora una volta. $N, sei davvero $gun uomo:una donna; interessante. Se solo ce ne fossero di più, come te!$B$BTi meriti una ricompensa: cosa preferisci?', 0),
(11245, 'itIT', 'Ottima mira, $gsignore:signora;! Devo ricordarmi di pagare da bere ai Cannonieri del Forte.', 0),
(11246, 'itIT', 'Bene, $gsignore:signora;. Pur essendo un compito piuttosto particolare, devo dire che ci avete messo un bel po'' d''impegno.$B$B<Il Sergente ti guarda con una punta di diffidenza e timore.>$B$BSe non vi dispiace, mi riprendo il machete. Ha perso un po'' il filo e non vogliamo che vi scivoli di mano, accoltellando anche me.', 0),
(11247, 'itIT', 'Molto bene, $gsignore:signora;. Senza di voi, tutto questo non sarebbe mai stato possibile.$B$BSono sicuro che il Capitano sarà felice di sapere ciò che abbiamo fatto qui.', 0),
(11248, 'itIT', 'È un piacere conoscervi, $gsignore:signora;! Non vedo l''ora di lavorare con voi.$B$BA proposito, c''è molto da fare.', 0),
(11249, 'itIT', 'Sì, $gfiglio mio:figlia mia;. Si direbbe un rituale malvagio e hai fatto la cosa giusta.$B$BGrazie per avermi portato questo rotolo, non vedo l''ora di studiarne le implicazioni. Se posso azzardare una previsione, direi che i Vrykul hanno trovato il modo di trascendere la morte... perlomeno per chi ne è degno.$B$BSconfiggendo il Thane di Geloskorn, ne hai dimostrato il poco valore. Solo la Luce sa cosa sarebbe potuto diventare, e quale terrore avrebbe sparso su di noi, se non lo avessi ucciso.', 0),
(11267, 'itIT', 'Il corno è freddo come questa regione... forse addirittura più freddo!$B$BAnche se non resteremo qui ancora a lungo, hai salvato dalla distruzione l''Accampamento degli Zoccolo Artico. $N, sei davvero $gun uomo:una donna; interessante. Forse la razza $r al di là dell''oceano non è così male, dopotutto.$B$BTi meriti una ricompensa, cosa preferisci?', 0),
(11313, 'itIT', '<Lurielle prende silenziosamente i Nuclei dalle tue mani.>$B$BGrazie, $N.$B$B<Lurielle guarda tristemente i Nuclei di Ghiaccio.>$B$BAmici miei, vi prometto che farò tutto il possibile per salvarvi.', 0),
(11331, 'itIT', 'Sì, $N? Che succede?$B$BCOME?!? Una super Piaga dei Reietti che ti scioglie all''istante?$B$BAvete trasformato il mio Prigioniero Vrykul in melma?$B$B<Il Capitano sembra quasi triste e sputa per il disgusto.>$B$BE va bene... ora so quello che devo fare. O meglio... quello che TU devi fare!', 0),
(11332, 'itIT', 'Ben fatto, $N... davvero ben fatto!$B$B<Il Capitano sembra fuori di sé dalla gioia.>$B$BQuei buoni a nulla dei Reietti ci penseranno due volte prima di crearci problemi!$B$BDirei che ti sei $gmeritato:meritata; qualcosa dal tesoro!', 0),
(11360, 'itIT', 'Sei $gfradicio:fradicia; e $gsporco:sporca; di fuliggine! Devi aver spento molti roghi!$B$BBen fatto! Come membro onorario dei Pompieri di Borgodoro, ti chiedo di tornare, se un giorno il villaggio avesse ancora bisogno di te!', 0),
(11395, 'itIT', '$N, so cos''è! È uno strumento di controllo dei Cristalli del Flagello!$B$BScommetto che può essere usato per disattivare i loro campi di forza. Mmm...$B$B<L''Esploratore appare pensieroso mentre riflette sulle implicazioni del fatto che tu abbia quello strumento.>', 0),
(11396, 'itIT', 'Bene!$B$B<Jaren si guarda rapidamente intorno per assicurarsi che nessuno abbia notato la sua esultanza.>$B$BScegli uno degli oggetti che ho trovato mentre ero qui, te lo sei $gmeritato:meritata;.$B$BInoltre, $N, nel caso tornassi alla Chiusa d''Acciaio, di'' a Irena che la amo e falle sapere che sto bene.', 0),
(11398, 'itIT', '$N, so cos''è! È lo strumento di controllo di quei Cristalli del Flagello!$B$BScommetto che può essere usato per disattivare i loro campi di forza. Mmm...$B$B<La Speziale appare pensierosa mentre riflette sulle implicazioni del fatto che tu abbia quello strumento.>', 0),
(11407, 'itIT', 'Hai mantenuto la parola informando la gente sui nostri Mastri Birrai. Grazie. Ti avevo promesso dei biglietti e sono felice di consegnarteli. Scommetto che i Troll sono di manica corta, quando si tratta di dare biglietti...$B$BTorna un altro giorno per aiutarci ancora a spargere la voce sulla Festa della Birra.', 0),
(11412, 'itIT', 'Grazie mille! Con la Festa della Birra in corso, gli attacchi dei Nani Ferroscuro e il nostro fornitore bloccato nel canyon, ho bisogno d''aiuto per la consegna dei barili. Quindi, se vuoi lavorare ancora in cambio di biglietti, torna a parlarmi ogni giorno.$B$BEcco la tua ricompensa: divertiti!', 0),
(11564, 'itIT', 'Ah, sì, queste andranno bene.$B$BPosale dove ti pare. Se vuoi, puoi mangiare gli avanzi dello stufato di ieri.', 1),
(11608, 'itIT', 'Questo dovrebbe fermarli... o almeno credo. A ogni modo, hai fatto la tua parte. Cos''altro potrebbe volere un $R?', 0),
(11618, 'itIT', 'Tutto qui? Malogrido ha inviato $gun solo ragazzo:una sola ragazza; $R?$B$BSe avessi ancora la mandibola, a quest''ora sarebbe per terra.', 0),
(11633, 'itIT', '<Il Capo Tribù Bora Fredda ti ascolta mentre riferisci ciò che hai appreso.>$B$BLe informazioni da te raccolte ci aiuteranno a pianificare l''attacco all''Acropoli. Dobbiamo solo trovare il modo di sconfiggere gli ufficiali che hai identificato e di entrare nella necropoli.', 1),
(11639, 'itIT', 'I morti ricevono onore dalle tue azioni, $N.$B$B<L''Orco ferito annuisce ed espira lentamente.>$B$BForse ora posso rialzarmi e tornare a essere il $C di un tempo.', 0),
(11652, 'itIT', 'Kel''Thuzad? Dunque è vero... Naxxramas sta tornando.$B$BForse ti avevo sottovalutato, $N. Hai reso all''Orda un grande servizio. Il Capoguerra ne sarebbe orgoglioso!$B$B<Garrosh si ferma a riflettere.>$B$BSe davvero c''è Kel''Thuzad al comando di queste truppe, chissà cos''altro ha in serbo per noi il Re dei Lich... Mi occorre del tempo per elaborare queste informazioni, $N. Puoi andare.', 0),
(11707, 'itIT', 'Vedo che finalmente Saltacieli è riuscito a mandarmi dei rinforzi. E appena in tempo!$B$B$gBenvenuto:Benvenuta;, $gfratello:sorella;, abbiamo disperato bisogno del tuo aiuto!', 0),
(11941, 'itIT', 'Molto saggio da parte tua portarmelo, $N.$B$B<Raelorasz osserva il frammento e annuisce lentamente.>$B$BSe davvero desideri contribuire alla nostra causa, quali che siano i rischi da correre, ti spiegherò di che si tratta.', 0),
(11978, 'itIT', 'Questo è esattamente ciò che ci serve, $N! Brandire armi dell''Orda solleverà il loro morale e darà loro la protezione di cui hanno bisogno contro il Flagello.$B$BSei $gpronto:pronta; per la cerimonia di iniziazione?$B$B<Brighthoof annuisce.>$B$BSarai tu a introdurre i nostri nuovi alleati nell''Orda.', 0),
(12005, 'itIT', 'Molto bene, $c. Ora mettili lì a terra, di fronte al trono di Agmar.$B$B<Sul volto dell''immagine dell''Arcimago compare l''ombra di un sorriso.>$B$BPeccato che Goramosh abbia rivelato che l''accordo era già stato raggiunto.$B$BA ogni modo, sono due pericoli in meno di cui preoccuparci. Ora pensiamo a questioni più urgenti.', 0),
(12032, 'itIT', 'Hai parlato con Oacha''noa?$B$BSe lei dice che dobbiamo sostenere il tuo popolo, allora lo faremo. L''Anziano Ko''nani lo accetterà come nostro destino, che gli piaccia o no.$B$BLa mia gente crede che tutte le anime siano un tutt''uno con la magia del mondo. Dobbiamo opporci ai tentativi dei Draghi Blu di controllare la magia o sarà la fine!$B$BNon avrei mai pensato che uno della tua razza potesse diventare il Campione dei Kalu''ak, ma hai dimostrato che mi sbagliavo. Ti ringrazio a nome del mio popolo, $N.$B$BPossano gli dei sorriderti e proteggerti.', 1),
(12057, 'itIT', '<Gort prende il tomo dalle tue mani.>$B$BSelvaggi... l''hanno rilegato con la pelle di un $R... Questa lingua... la sua esistenza non è mai stata provata. È la lingua della morte... la lingua del Flagello.', 0),
(12115, 'itIT', 'Ci sono solo due cose nella vita che mi interessano, e nessuna delle due prevede tradurre un tomo del Flagello per te.$B$BTuttavia... forse potremmo raggiungere un accordo.$B$B<Koltira sfodera la sua arma.>$B$BQuesta è la mia Lama Runica. Si chiama Lamagelida. Essa brama il sangue del Re dei Lich e dei suoi servitori, ma prima devo inciderla con delle rune del potere: i simboli di Gelo, Sangue ed Ombra. Portami delle fonti di potere adatte e tradurrò il tomo.', 0),
(12180, 'itIT', '<Il Montanaro Kilian ti ascolta, mentre gli riferisci le parole dei Prospettori prigionieri.>$B$BHanno menzionato Kronus e una guerra contro i Giganti della Pietra? Davvero?$B$BAllora l''istinto di Raegar aveva ragione. Dobbiamo trovare il modo di entrare e scoprirne di più sui loro piani.', 0),
(12185, 'itIT', 'Possibile che Kronus non stia esagerando affatto? I figli dei Titani, divisi in Pietra e Ferro, che combattono per il controllo dell''antica città di Ulduar. È una follia, $N, e potrebbe distruggere la nostra unica possibilità di conoscere la vera storia dei Nani!', 0),
(12253, 'itIT', '<Halford recita una preghiera per i morti.>$B$BHai fatto la volontà della Luce, $N.$B$BTemo che il nostro lavoro sia solo all''inizio.$B$B<Halford solleva un documento.>', 0),
(12273, 'itIT', '<Ti è sembrato di vedere un accenno di sorriso sul volto di Wroth, prima che tornasse serio.>$B$BSei $gil mio $c preferito:la mia $c preferita;, $N. Mi piacerebbe che entrassi a far parte della Mano della Vendetta come ufficiale.$B$BPotresti iniziare come Guardiamorte e diventare Apprendista Esecutore nel giro di pochi decenni!$B$BNo? Non prendere decisioni affrettate... Pensaci bene prima di darmi una risposta.', 0),
(12281, 'itIT', '<Halford apre il pacco e legge le analisi.>$B$BIo non sono uno scienziato, $N, dunque mi scuserai per il mio linguaggio dimesso. Se non ho capito male, e questo lo capirebbe anche un bambino, da queste analisi emerge che non sappiamo un bel niente sulla macchina da guerra del Flagello. L''unica cosa che abbiamo scoperto è che il Flagello usa questo metallo per realizzare le sue macchine d''assedio, le corazze e le armi.$B$B<Halford emette un lungo sospiro.>', 0),
(12517, 'itIT', 'La tua abilità con la penna comincia già a farsi notare, giovane scriba. Le carte dei tarocchi sono molto importanti per la Fiera di Lunacupa, dunque non esitare a chiamarci se dovessi crearne delle altre. Vorremmo sdebitarci con te offrendoti, in cambio delle carte, degli oggetti recuperati dai nostri abili mercanti.', 0),
(12544, 'itIT', '<Hemet ascolta mentre racconti cos''hai scoperto.>$B$BCosì si fa. Nessun rinocorno morto dirà a Hemet Nesingwary dove e cosa può cacciare. Gliela faremo vedere a quel mucchio di ossa.', 1),
(12545, 'itIT', 'Come puoi vedere, la macchina da guerra del Flagello continua ad avanzare, mentre gli eserciti dell''Orda e dell''Alleanza restano divisi, costituendo un bersaglio facile. È per questo che dobbiamo rimanere uniti.$B$B<Valus si perde per un attimo nei suoi pensieri.>$B$BLa Crociata d''Argento ha bisogno di gente come te. Ti andrebbe di unirti alla nostra causa e combattere e morire con il Brandicenere?', 1),
(12554, 'itIT', 'Sei $gl''eroe:l''eroina; del giorno, $N.$B$B<Moonshard allontana la testa con un calcio.>$B$BMeriti il nostro più profondo rispetto, e credo anche qualcosa di più.', 0),
(12643, 'itIT', '<Stefan vaglia i componenti.>$B$BSiamo lontani dalla perfezione, ma dobbiamo accontentarci.$B$BOra fatti forza, $c, perché arriva la parte più difficile...', 0),
(12687, 'itIT', '$N, sei $griuscito:riuscita; là dove molti iniziati falliscono. Per questo ti meriti una ricompensa.$B$B<Salanar si inchina.>', 0),
(12700, 'itIT', 'Ci hai serviti bene, Cavaliere della Morte. Pochi dei tuoi compagni sono sopravvissuti al nostro attacco iniziale contro gli intrusi Scarlatti. Tu sei tra i più forti.$B$B<Il Principe Valanar annuisce.>$B$BA est, oltre la Miniera di Borgorado, si trova la costa che la Crociata Scarlatta chiama Rivachiara. Ci sono migliaia di soldati tra noi e le loro navi. Pensi siano un ostacolo insormontabile? Io non credo...', 0),
(12706, 'itIT', '<Il Gran Signore Mograine legge il rapporto.>$B$BL''INTERA Flotta Scarlatta?$B$B<Il Gran Signore Mograine annuisce.>$B$BUn simile potere, $N... Non vedevo una tale dimostrazione di forza da anni... da quando mio padre...$B$B<Il Gran Signore Mograine scuote la testa.>$B$BNon importa...$B$BOra pensiamo alla tua ricompensa, prima che me ne dimentichi.', 0),
(12719, 'itIT', 'Il registro ci dirà molte cose su quegli insetti Scarlatti.$B$B<Keleseth sfoglia le pagine del registro.>$B$BTasso di mortalità, tasso di natalità, ma soprattutto movimenti.$B$BGuarda qua, $N, hanno già inviato tre vascelli. Vediamo un po'' dove sono diretti...$B$B<Keleseth borbotta qualcosa su latitudine e longitudine tra sé e sé mentre calcola la rotta.>$B$BCOSA? Non è possibile. Sono diretti a Nordania!$B$BAccanto alle coordinate ci sono le parole: "Alba Cremisi".', 0),
(12740, 'itIT', 'Sei una brava persona, $N. Siamo stati fortunati che sei $gpassato:passata; da qui.$B$BRimani con noi per un po''. Sono certo che abbiamo altri compiti per $gun:una; capace $c come te.', 0),
(12778, 'itIT', 'Mi hai servito bene, $N. Il marchio del Flagello è stato impresso a fuoco su queste Terre Scarlatte. Hai seminato morte e distruzione a perdita d''occhio e mi hai consegnato gli ultimi eserciti Scarlatti.$B$B<Il Re dei Lich indica le rovine di Borgorado e la città in fiamme di Nuova Avalon.>$B$BOra è tempo di completare l''opera.', 0),
(12779, 'itIT', 'Inginocchiati, campione. L''elmo che ora poserò sulla tua testa ti darà un aspetto terrorizzante. Chiunque oserà guardare il tuo volto oscuro saprà di andare incontro alla morte. Che nessuno abbia l''ardire di sfidare il tuo re o la tua ira spietata, $N.$B$BC''è un''ultima cosa da fare...$B$B<Il Re dei Lich guarda verso ovest.>$B$BLa Cappella della Luce.', 0),
(12824, 'itIT', 'Hai fatto saltare tutto in aria? Favoloso! Scommetto che Rio era al settimo cielo.$B$BTi siamo davvero grati per tutto l''aiuto che ci hai dato, $N. Che ne dici di un ricordo in cambio del tuo lavoro?', 0),
(12842, 'itIT', 'Ricordati queste parole, Cavaliere della Morte: la Forgia delle Rune è uno strumento del Flagello. Essa esiste solo ad Acherus, Naxxramas e nel cuore della Corona di Ghiaccio! Puoi decorare le tue armi solo presso una Forgia delle Rune.$B$BTorna spesso per decorare tutte le tue armi. Un Cavaliere della Morte deve farsi trovare sempre $gpronto:pronta; ad affrontare i propri nemici!', 0),
(13082, 'itIT', '<Mentre ti avvicini al Crociato Bridenbrad, non puoi fare a meno di notare che la sua pelle ha assunto un colorito pallido e che i suoi respiri sono vuoti. È evidente che gli resta poco tempo.>$B$B$c, sei $gtornato:tornata; da me ancora una volta. Confesso... che sono felice di vederti. Il tuo viso mi fa sperare che presto questa terra sarà libera dalla morsa di Arthas. Sono orgoglioso di averti conosciuto...$B$B<Le parole di Bridenbrad si spengono, mentre un debole sorriso gli illumina il volto. Quando la vita sembra abbandonarlo, un lieve tintinnio ti riempie le orecchie.>', 0),
(13092, 'itIT', 'Scopriamo cosa ha in serbo per te il futuro!$B$B<La Megera d''Ossa lancia le ossa sulla stuoia davanti a lei.>$B$B$c, scegli il tuo fato!', 1),
(13164, 'itIT', 'Mograine in persona è venuto a controllare? Credo che fra i due non scorresse buon sangue, quindi non mi stupisce che abbia voluto un pezzo di quel disgraziato.$B$B$r, te la sei cavata benissimo e sarai ricompensato di conseguenza. La Spada d''Ebano ti ringrazia.', 1),
(13207, 'itIT', 'Sei $gun ragazzo:una ragazza; di poche risposte e molte domande, eh?', 0),
(13219, 'itIT', 'La tua vittoria sul Principe Sandoval mi dà il voltastomaco. Un lurido pezzente come te avrebbe dovuto perdere apposta, come gesto di gratitudine per averlo incontrato e aver ricevuto l''enorme dono di potersi inginocchiare ai suoi piedi.$B$BTi sei meritato la tua maledetta ricompensa: scegli in fretta.', 1),
(13287, 'itIT', 'Davvero, $c?$B$BNon hai niente di rilevante da riferire?$B$B<Thassarian nota i resti dell''abominio schizzati sui tuoi vestiti e sorride.>$B$BMi permetto di dissentire...', 0),
(13314, 'itIT', '$N, sono felice di vedere che le missioni sono in mano a persone competenti. Se solo avessimo un esercito di eroi come te, potremmo dimostrare all''Orda di che stoffa siamo fatti. I rapporti che hai recuperato ci permetteranno di mantenere un vantaggio in questo scontro. Siamo piegati, ma non ci spezzeremo mai!', 1),
(13343, 'itIT', 'Santo cielo, ce l''hai fatta! Non ne ero sicura.$B$BSei $gentrato:entrata; e $guscito:uscita; dal flusso temporale per un attimo durante il combattimento! Credevo che ti avessimo $gperso:persa;!$B$BE invece sei qui, ancora $gtutto intero:tutta intera;, dopo aver salvato la tua versione del passato dall''altro lato del ciclo temporale in cui ti trovavi.$B$BSei $gl''eroe:l''eroina; del tempo, $N!', 0),
(13420, 'itIT', '<Il riflesso del semprefreddo brilla negli occhi di Calder mentre lo tiene sollevato.>$B$BAhhh, Semprefreddo. Il simbolo del cuore della nostra gente...$B$BUn tempo in questa regione ce n''era in abbondanza. Con il passare degli anni, però, gli jormungar l''hanno divorato quasi tutto. Ora per noi è molto raro e molto prezioso.$B$BMentre percorri queste terre, tieni gli occhi aperti per altri pezzi. Nel caso ne trovassi degli altri, portameli. Te ne sarò molto grato.', 1),
(13811, 'itIT', 'Ben fatto. Allenarsi con gli altri valorosi è uno dei modi migliori per prepararsi ad affrontare il torneo. So che renderai onore all''Orda, $N.', 0),
(13861, 'itIT', 'La Crociata d''Argento è fiera di avere eroi come te che combattono al nostro fianco contro il Re dei Lich.', 0),
(24848, 'itIT', 'Non... non sei Snivel. Ti manda lui? È così in ritardo, che iniziavo a perdere le speranze...$B$B<Non appena realizza che non sei qui per riferirle un messaggio da parte di Snivel, gli occhi della donna iniziano a riempirsi di lacrime.>$B$BIl mio Snivel non si comporterebbe mai in questo modo, eppure... non posso negare l''evidenza.', 1),
(24850, 'itIT', 'Non sei Snivel. Mi ha dato appuntamento qui, ma è già passata un''ora e non si vede! Che gli hai fatto?$B$B<Roka si calma, quando le dici che anche tu stai cercando Snivel e gli occhi le si riempiono di lacrime.>$B$BIl mio Snivel non si comporterebbe mai così. Credi gli sia successo qualcosa?', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(11619, 'itIT', 'Hai ucciso Gamel, $r?', 1),
(12320, 'itIT', 'Vieni dall''alto comando, $gfigliolo:figliola;?', 0),
(12455, 'itIT', 'Dove sono le mie munizioni, $gamico:amica;?', 0),
(12517, 'itIT', 'Vedo che sei $griuscito:riuscita; a incidere un Mazzo dei Ladri! Ben fatto.', 0),
(13131, 'itIT', 'Come va, $gamico:amica;?', 0);
