-- Quest details and objectives with the NPC names used by AzerothCore (these fields are still empty in the itIT rows)
UPDATE `quest_template_locale` SET `Details` = 'Abbiamo altri sciocchi da farti uccidere.$B$BI miei agenti mi hanno detto che diversi dei nostri cittadini più in vista sono finiti nelle mani della Furia Scarlatta.$B$BCosì non va bene.$B$BTorna a Nuova Valsalda ed elimina la Guardiamorte Schneider, l''Esperto Scrivano Barriga, l''Ingegnere Burke e il Cancelliere Amai.$B$BDa quello che ho saputo, si trovano sparsi per tutta la zona. Saranno sicuramente rinchiusi in gabbia, in attesa di essere torturati.$B$BParla con loro e poi uccidili!', `Objectives` = 'La Maestra delle Spie Repine ti ha chiesto di uccidere la Guardiamorte Schneider, l''Esperto Scrivano Barriga, l''Ingegnere Burke e il Cancelliere Amai.$B$BQuando hai finito, torna dal Gran Esecutore Wroth a Venefica per informarlo del tuo successo.', `VerifiedBuild` = 0 WHERE `ID` = 12245 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Ora basta! Voglio che metti fine alla tortura della mia gente!$B$BIl Torturatore della Furia LeCraft sta estorcendo informazioni da tutti coloro che vengono catturati da quei demoni! Devo sapere che cosa ha scoperto.$B$BLe mie fonti mi dicono che ora lavora nei sotterranei della loro caserma, vicino alla forgia.$B$BTi presterò il mio personale ferro per marchiare per portare a termine il lavoro.$B$BTrovalo e ottieni le informazioni che mi servono.', `Objectives` = 'Il Gran Esecutore Wroth a Venefica ti ha chiesto di usare il Ferro per Marchiare 5 volte sul Torturatore LeCraft per farlo parlare. Una volta ottenute le informazioni che ti servono, uccidilo.', `VerifiedBuild` = 0 WHERE `ID` = 12252 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = '<Una verga cade dalla mano di LeCraft. Ci sono delle rune magiche pulsanti lungo tutta la sua struttura.>$B$B<Che sia lo strumento con cui estorceva le informazioni dai prigionieri?>$B$B<Meglio portare la verga al Gran Esecutore per farla esaminare.>', `VerifiedBuild` = 0 WHERE `ID` = 12271 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Objectives` = 'Sire Afrasastrasz al Tempio della Lega dei Draghi ti ha chiesto di uccidere 3 Draghi di Zaffiro, 5 Drachi di Zaffiro e di destabilizzare il Santuario dei Draghi di Zaffiro mentre cavalchi un Difensore della Lega dei Draghi in battaglia.', `VerifiedBuild` = 0 WHERE `ID` = 12372 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Carri, cumpà. Sto parlando di macchine d''assedio! Abbiamo carri corazzati sulla costa a ovest, all''Approdo di Garrosh. Dovrai raggiungere i carri e usarne uno per portare la giustizia dell''Orda sul Flagello!$B$BLa parte difficile sta nel farti arrivare laggiù: per nessun motivo al mondo ti lasceremmo andare con le Viverne dei Venti nuostr'', è troppo rischioso.$B$BVedi chell''Elfo biondo laggiù? Si chiama Yanni, cumpà. Isso ti può portare sulla costa in tutta sicurezza. Na volta $garrivato:arrivata;, parla con Gorge il Tritacadaveri!', `Objectives` = 'Parla con Yanni al Forte dei Cantaguerra per organizzare un viaggio sicuro verso l''Approdo di Garrosh. Una volta a destinazione, parla con Gorge il Tritacadaveri.', `VerifiedBuild` = 0 WHERE `ID` = 11636 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Grazie per tutto il tuo aiuto. Puoi riferire a Gorge che i carri sono pronti all''azione. Con un po'' di fortuna, renderai questo posto sicuro una volta per tutte!', `Objectives` = 'Parla con Gorge il Tritacadaveri alla Costa dell''Eco.', `VerifiedBuild` = 0 WHERE `ID` = 11651 AND `locale` = 'itIT';

